-- Fictional, clearly labeled simulated bot engagement; not real user accounts.
CREATE TABLE IF NOT EXISTS x_bot_reach(post_id TEXT PRIMARY KEY REFERENCES x_posts(id),bot_likes INTEGER NOT NULL DEFAULT 0,bot_reposts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(bot_likes BETWEEN 0 AND 1000000),CHECK(bot_reposts BETWEEN 0 AND 1000000)); CREATE TRIGGER IF NOT EXISTS x_bot_reach_seed AFTER INSERT ON x_posts WHEN NEW.reply_to IS NULL AND NEW.repost_of IS NULL BEGIN INSERT INTO x_bot_reach(post_id,bot_likes,bot_reposts) VALUES(NEW.id,100+abs(random()%1000),abs(random()%100)); END;
